if($check && $check->num_rows){$orders=(int)($conn->query("SELECT COUNT(*) total FROM pesanan")->fetch_assoc()['total']??0);$revenue=(float)($conn->query("SELECT COALESCE(SUM(total),0) total FROM pesanan")->fetch_assoc()['total']??0);}
